base=re.sub(r'<section id="manual".*?</section>', '''<section id="manual" class="view"><div class="intro"><div><h2>工事マニュアル</h2><p>Volume 1の使い方と、保存・共有の手順を確認できます。</p></div></div><div class="panel"><h3>操作ガイド</h3><p>工事選択、積算・設計、書類の状態、業者への依頼、JSONと添付ZIPの保存、共有差分の確認をまとめています。</p><a href="volume1.html" target="_blank" rel="noopener">Volume 1の使い方を開く</a><p>書類ごとの目的・準備・確認は「工事提出書類」の各項目でも確認できます。</p></div></section>''',base,flags=re.S)
